     1→/**
     2→ * Environmental Accumulation System (Phase 2: Golden Age & Accumulation Systems)
     3→ * 
     4→ * Tracks environmental costs that accumulate silently from production/growth,
     5→ * then manifest as crises when thresholds are crossed.
     6→ * 
     7→ * Mechanisms modeled:
     8→ * - Resource depletion: Extraction > regeneration → reserves decline
     9→ * - Pollution accumulation: Production → waste → contamination builds
    10→ * - Climate degradation: Energy use + emissions → stability declines
    11→ * - Biodiversity loss: Expansion + habitat disruption → ecosystems collapse
    12→ * 
    13→ * Key insight: High QoL can persist while environmental debt accumulates.
    14→ * This creates the "Golden Age illusion" - prosperity masking future collapse.
    15→ */
    16→
    17→import { GameState, EnvironmentalAccumulation } from '@/types/game';
    18→import { levyFlight, ALPHA_PRESETS } from './utils/levyDistributions';
    19→import { updateCatastropheTracking } from './calculations';
    20→import { RootCause } from '@/types/population';
    21→import { calculateClimatePovertyWeights, calculateEcosystemWeights } from './utils/deathAttribution';
    22→
    23→/**
    24→ * Initialize environmental accumulation state
    25→ * 
    26→ * Starting values represent 2025 REALISTIC baseline (research-backed):
    27→ * - Resources: 1.7x overshoot (Global Footprint Network 2025)
    28→ * - Pollution: 46% unhealthy air (American Lung Assoc 2025)
    29→ * - Climate: +1.2°C warming (Copernicus 2024)
    30→ * - Biodiversity: 50-70% loss since 1970 (IPBES 2024)
    31→ */
    32→export function initializeEnvironmentalAccumulation(): EnvironmentalAccumulation {
    33→  return {
    34→    resourceReserves: 0.65,      // Was 0.85 - Research: 1.7x overshoot (GFN 2025), Earth Overshoot Day July 24
    35→    pollutionLevel: 0.30,         // Was 0.15 - Research: 46% unhealthy air (ALA 2025), 7/9 boundaries breached
    36→    climateStability: 0.75,       // KEEP - Validated (Copernicus 2024: +1.2°C warming)
    37→    biodiversityIndex: 0.35,      // Was 0.70 - Research: 50-70% loss since 1970 (IPBES 2024)
    38→    resourceCrisisActive: false,
    39→    pollutionCrisisActive: false,
    40→    climateCrisisActive: false,
    41→    ecosystemCrisisActive: false
    42→  };
    43→}
    44→
    45→/**
    46→ * Apply stochastic variance to environmental rates
    47→ * Reflects uncertainty in climate/ecological models (IPCC uncertainty bounds, etc.)
    48→ * 
    49→ * P2.1: Added to prevent determinism and reflect scientific uncertainty
    50→ * Research: IPCC AR6 reports uncertainty ranges (e.g., SSP5-8.5: 3.3-5.7°C)
    51→ * 
    52→ * @param baseRate - The base degradation/depletion rate
    53→ * @param variance - Variance as fraction (0.25 = ±25%, range 75%-125% of base)
    54→ * @returns Modified rate with stochastic variation
    55→ */
    56→function applyStochasticVariance(baseRate: number, variance: number = 0.25): number {
    57→  const multiplier = (1 - variance) + Math.random() * (2 * variance);
    58→  return baseRate * multiplier;
    59→}
    60→
    61→/**
    62→ * Update environmental accumulation based on economic activity
    63→ * 
    64→ * Called each month to track accumulation rates.
    65→ * Rate-based: high production = faster accumulation (unless mitigated)
    66→ */
    67→export function updateEnvironmentalAccumulation(
    68→  state: GameState
    69→): void {
    70→  const env = state.environmentalAccumulation;
    71→  const economicStage = state.globalMetrics.economicTransitionStage;
    72→  const manufacturingCap = state.globalMetrics.manufacturingCapability;
    73→  
    74→  // Check if we have technologies that mitigate environmental impact
    75→  const hasFusion = state.technologyTree.some(t => t.id === 'fusion_energy' && t.completed);
    76→  const hasAdvancedMaterials = state.technologyTree.some(t => t.id === 'advanced_materials' && t.completed);
    77→  const hasNanotech = state.technologyTree.some(t => t.id === 'molecular_manufacturing' && t.completed);
    78→  const hasCleanEnergy = state.technologyTree.some(t => t.id === 'clean_energy' && t.completed);
    79→  const hasRecycling = state.technologyTree.some(t => t.id === 'advanced_recycling' && t.completed);
    80→  const hasEcosystemManagement = state.technologyTree.some(t => t.id === 'ecosystem_management_ai' && t.completed);
    81→  
    82→  // === RESOURCE DEPLETION ===
    83→  // P2.1: Global Footprint Network (2024) - 1.7x overshoot, worsening 0.5%/year
    84→  // Earth Overshoot Day: August 1 (2024) - using resources 1.7x faster than regeneration
    85→  // Target trajectory: (1/1.7) → (1/2.0) over 75 years = ~1.7%/year absolute decline
    86→  // Calibration: 0.00015 base rate achieves GFN overshoot worsening trajectory
    87→  let resourceDepletionRate = economicStage * 0.00015; // Was 0.008 (reduced 53x)
    88→
    89→  // High production accelerates depletion
    90→  // P2.1: Reduced to match empirical resource extraction acceleration
    91→  resourceDepletionRate += manufacturingCap * 0.0001; // Was 0.004 (reduced 40x)
    92→
    93→  // Rapid growth (stage transitions) spike depletion
    94→  // P2.1: Growth surges temporarily increase extraction (industrial buildout)
    95→  const stageGrowthRate = Math.max(0, economicStage - (economicStage - 0.1)); // Approximate growth
    96→  resourceDepletionRate += stageGrowthRate * 0.0006; // Was 0.03 (reduced 50x)
    97→  
    98→  // P2.1: Apply stochastic variance (±25% = economic/extraction variability)
    99→  resourceDepletionRate = applyStochasticVariance(resourceDepletionRate, 0.25);
   100→  
   101→  // Mitigation from technologies (old tech tree - may be deprecated)
   102→  if (hasAdvancedMaterials) resourceDepletionRate *= 0.5; // 50% reduction (material efficiency)
   103→  if (hasNanotech) resourceDepletionRate *= 0.25; // Additional 75% reduction (molecular manufacturing)
   104→  
   105→  // Mitigation from breakthrough technologies (Phase 2A)
   106→  // NOTE: Resource efficiency now handled by TechTreePhase regional effects
   107→  // No additional multiplier needed here
   108→  
   109→  // Apply depletion (with MIN_FLOOR to prevent exactly 0, which breaks geometric means)
   110→  const MIN_RESERVE_FLOOR = 0.001; // 0.1% minimum to prevent geometric mean collapse
   111→
   112→  // Detect NaN and fail loudly - don't hide bugs with fallbacks
   113→  if (isNaN(env.resourceReserves)) {
   114→    console.error(`❌ NaN in resourceReserves at month ${state.currentMonth}`);
   115→    console.error(`   environmentalAccumulation state: ${JSON.stringify(env)}`);
   116→    throw new Error(`NaN resource reserves - simulation corrupted at month ${state.currentMonth}`);
   117→  }
   118→
   119→  env.resourceReserves = Math.max(MIN_RESERVE_FLOOR, env.resourceReserves - resourceDepletionRate);
   120→  
   121→  // === RESOURCE REGENERATION (Phase 2.8) ===
   122→  // Tech-enabled recovery: Circular economy, sustainable agriculture, clean energy
   123→  // Research basis: Ellen MacArthur Foundation (2015), Tilton (2003)
   124→  // NOTE: Now handled by TechTreePhase regional effects
   125→  let resourceRegeneration = 0;
   126→  
   127→  // NOTE: Tech-based regeneration now calculated by TechTreePhase
   128→  // Old breakthrough tech system removed - tech tree handles all resource effects
   129→  
   130→  // Apply regeneration (can recover from 0%!)
   131→  env.resourceReserves = Math.min(1.0, env.resourceReserves + resourceRegeneration);
   132→  
   133→  // Log significant regeneration
   134→  if (resourceRegeneration > 0.02 && state.currentMonth % 12 === 0) {
   135→    console.log(`🌱 RESOURCE REGENERATION: ${(resourceRegeneration * 100).toFixed(1)}%/month (reserves: ${(env.resourceReserves * 100).toFixed(0)}%)`);
   136→  }
   137→  
   138→  // === POLLUTION ACCUMULATION ===
   139→  // Base pollution from production
   140→  let pollutionRate = economicStage * 0.006; // 0.6% per month at Stage 1
   141→  
   142→  // Manufacturing capability increases pollution
   143→  pollutionRate += manufacturingCap * 0.005;
   144→  
   145→  // Rapid industrial growth spikes pollution
   146→  if (economicStage > 2.0 && economicStage < 3.5) {
   147→    pollutionRate += 0.01; // Industrial transition period
   148→  }
   149→  
   150→  // Mitigation from clean technologies
   151→  if (hasCleanEnergy) pollutionRate *= 0.4; // 60% reduction
   152→  if (hasRecycling) pollutionRate *= 0.6; // Additional 40% reduction
   153→  if (hasNanotech) pollutionRate *= 0.5; // Molecular precision reduces waste
   154→  
   155→  // Natural degradation (Earth can process some pollution)
   156→  const naturalDegradation = 0.003; // 0.3% per month natural cleanup
   157→  
   158→  // Detect NaN before calculation - fail loudly
   159→  if (isNaN(env.pollutionLevel)) {
   160→    console.error(`❌ NaN in pollutionLevel BEFORE calculation at month ${state.currentMonth}`);
   161→    console.error(`   pollutionRate: ${pollutionRate}, naturalDegradation: ${naturalDegradation}`);
   162→    console.error(`   environmentalAccumulation state: ${JSON.stringify(env)}`);
   163→    throw new Error(`NaN pollution level - simulation corrupted at month ${state.currentMonth}`);
   164→  }
   165→
   166→  // Apply pollution (accumulation - degradation)
   167→  env.pollutionLevel = Math.max(0, Math.min(1, env.pollutionLevel + pollutionRate - naturalDegradation));
   168→
   169→  // Detect NaN after calculation - this means the calculation itself produced NaN
   170→  if (isNaN(env.pollutionLevel)) {
   171→    console.error(`❌ NaN in pollutionLevel AFTER calculation at month ${state.currentMonth}`);
   172→    console.error(`   pollutionRate: ${pollutionRate}, naturalDegradation: ${naturalDegradation}`);
   173→    throw new Error(`Pollution calculation produced NaN - check pollutionRate/naturalDegradation`);
   174→  }
   175→  
   176→  // === CLIMATE DEGRADATION ===
   177→  // Energy usage drives climate impact
   178→  // Proxy: compute infrastructure + manufacturing + economic stage
   179→  const totalCompute = state.computeInfrastructure.dataCenters
   180→    .filter(dc => dc.operational)
   181→    .reduce((sum, dc) => sum + dc.capacity * dc.efficiency, 0);
   182→
   183→  const energyUsage = (totalCompute / 10000) + manufacturingCap + (economicStage * 0.3);
   184→
   185→  // P2.1: IPCC AR6 WG1 (2021) - 0.2°C/decade current warming = 0.0167°C/year = 0.00139°C/month
   186→  // Target: 75-year simulation reaches ~40% degradation (catastrophe threshold) = 0.53%/month
   187→  // Calibration: 0.00015 base rate achieves IPCC SSP5-8.5 trajectory (+4.4°C by 2100)
   188→  let climateDegradationRate = energyUsage * 0.00015; // Was 0.0008 (reduced 5.3x)
   189→
   190→  // Stage 3-4 transition: Accelerating emissions from rapid industrialization
   191→  // Positive feedbacks (permafrost, ice-albedo) emerge after critical thresholds
   192→  // P2.1: Reduced from 0.0016 to achieve ~700-900 month collapse timeline
   193→  if (economicStage > 3.0) {
   194→    climateDegradationRate += 0.0003; // Was 0.0016 (reduced 5.3x)
   195→  }
   196→  
   197→  // P2.1: Apply stochastic variance (±20% = IPCC uncertainty bounds)
   198→  climateDegradationRate = applyStochasticVariance(climateDegradationRate, 0.20);
   199→  
   200→  // Mitigation from clean energy
   201→  if (hasFusion) climateDegradationRate *= 0.2; // 80% reduction (fusion is near-zero carbon)
   202→  if (hasCleanEnergy) climateDegradationRate *= 0.5; // 50% reduction
   203→  
   204→  // Natural stabilization (very slow)
   205→  const naturalStabilization = 0.001; // 0.1% per month
   206→  
   207→  // Detect NaN before calculation - fail loudly
   208→  if (isNaN(env.climateStability)) {
   209→    console.error(`❌ NaN in climateStability at month ${state.currentMonth}`);
   210→    console.error(`   climateDegradationRate: ${climateDegradationRate}, naturalStabilization: ${naturalStabilization}`);
   211→    console.error(`   environmentalAccumulation state: ${JSON.stringify(env)}`);
   212→    throw new Error(`NaN climate stability - simulation corrupted at month ${state.currentMonth}`);
   213→  }
   214→
   215→  // Apply climate degradation (with MIN_FLOOR to prevent exactly 0, which breaks geometric means)
   216→  const MIN_CLIMATE_FLOOR = 0.001; // 0.1% minimum to prevent geometric mean collapse
   217→  env.climateStability = Math.max(MIN_CLIMATE_FLOOR, Math.min(1, env.climateStability - climateDegradationRate + naturalStabilization));
   218→  
   219→  // === BIODIVERSITY LOSS ===
   220→  // Habitat disruption from expansion
   221→  // P2.1: IPBES 2019 Global Assessment - 1.5%/year decline = 0.125%/month target
   222→  // Target: 10-20% decline by Month 300 (25 years), not 99% by Month 60
   223→  // Multi-factor model: Base rate + compounding effects from all environmental stressors
   224→  let biodiversityLossRate = economicStage * 0.00006; // Was 0.0004 (reduced 6.7x)
   225→
   226→  // Manufacturing and resource extraction destroy habitats
   227→  // P2.1: Reduced compounding factors to achieve IPBES timescale
   228→  biodiversityLossRate += manufacturingCap * 0.00004; // Was 0.0003 (reduced 7.5x)
   229→  biodiversityLossRate += (1 - env.resourceReserves) * 0.0001; // Was 0.0008 (reduced 8x)
   230→
   231→  // Pollution and climate degrade ecosystems
   232→  // P2.1: Critic identified compounding effects needed 6-8x reduction
   233→  biodiversityLossRate += env.pollutionLevel * 0.00005; // Was 0.0004 (reduced 8x)
   234→  biodiversityLossRate += (1 - env.climateStability) * 0.00008; // Was 0.0006 (reduced 7.5x)
   235→  
   236→  // P2.1: Apply stochastic variance (±30% = higher ecological uncertainty)
   237→  biodiversityLossRate = applyStochasticVariance(biodiversityLossRate, 0.30);
   238→  
   239→  // Mitigation from ecosystem management
   240→  if (hasEcosystemManagement) {
   241→    biodiversityLossRate *= 0.3; // 70% reduction (AI manages ecosystems)
   242→  }
   243→  
   244→  // Natural recovery (very slow without active management)
   245→  const naturalRecovery = hasEcosystemManagement ? 0.005 : 0.001;
   246→  
   247→  // Detect NaN before calculation - fail loudly
   248→  if (isNaN(env.biodiversityIndex)) {
   249→    console.error(`❌ NaN in biodiversityIndex at month ${state.currentMonth}`);
   250→    console.error(`   biodiversityLossRate: ${biodiversityLossRate}, naturalRecovery: ${naturalRecovery}`);
   251→    console.error(`   environmentalAccumulation state: ${JSON.stringify(env)}`);
   252→    throw new Error(`NaN biodiversity index - simulation corrupted at month ${state.currentMonth}`);
   253→  }
   254→
   255→  // Apply biodiversity loss
   256→  env.biodiversityIndex = Math.max(0, Math.min(1, env.biodiversityIndex - biodiversityLossRate + naturalRecovery));
   257→
   258→  // === P1.5: ECOSYSTEM REGENERATION FROM POPULATION DECLINE ===
   259→  // Historical evidence: Nature rebounds when human pressure reduces
   260→  // - Chernobyl Exclusion Zone: Wildlife thrives with humans gone (1986-present)
   261→  // - COVID-19 lockdowns: Air quality improved 30-60% in 2 months (2020)
   262→  // - Post-Black Death: Forest regrowth in Europe (1350-1400)
   263→  // - Mayan collapse: Jungle reclaimed cities in decades (800-900 CE)
   264→  // Research: Ecological succession takes 20-50 years, but initial recovery is fast
   265→  const currentPressure = state.humanPopulationSystem.population / state.humanPopulationSystem.carryingCapacity;
   266→
   267→  if (currentPressure < 0.5) { // Population below half of carrying capacity
   268→    // Regeneration rate scales with reduced pressure: 0-1% monthly
   269→    // At 50% pressure: 0%/month (no bonus)
   270→    // At 25% pressure: 0.5%/month
   271→    // At 0% pressure: 1%/month (maximum recovery)
   272→    const pressureReduction = 0.5 - currentPressure; // 0 to 0.5
   273→    const regenerationRate = pressureReduction * 0.02; // Up to 1% monthly
   274→
   275→    // Nature recovers when humans aren't actively destroying it
   276→    env.biodiversityIndex = Math.min(1.0, env.biodiversityIndex + regenerationRate);
   277→    env.resourceReserves = Math.min(1.0, env.resourceReserves + regenerationRate * 0.5); // 50% as fast
   278→    env.climateStability = Math.min(1.0, env.climateStability + regenerationRate * 0.3); // 30% as fast (carbon sinks recovering)
   279→
   280→    if (state.currentMonth % 24 === 0 && regenerationRate > 0.003) { // Log every 2 years if significant
   281→      console.log(`🌱 NATURAL REGENERATION: Low human pressure (${(currentPressure * 100).toFixed(0)}%), ecosystems recovering at +${(regenerationRate * 100).toFixed(2)}%/month`);
   282→      console.log(`   Biodiversity: ${(env.biodiversityIndex * 100).toFixed(1)}%, Resources: ${(env.resourceReserves * 100).toFixed(1)}%, Climate: ${(env.climateStability * 100).toFixed(1)}%`);
   283→    }
   284→  }
   285→
   286→  // === PHASE 1: LÉVY FLIGHT CASCADE CHECKS (Self-Organized Criticality) ===
   287→  // Research: Bak et al. (1987) - systems organize to critical states
   288→  // When environmental debt is high, minor events can trigger avalanches
   289→  // Most of the time: linear accumulation. Rarely: mega-cascade (power-law tails)
   290→
   291→  const criticalThreshold = 0.6; // System at edge of chaos
   292→
   293→  // Resource cascade (alpha=1.8 - fatter tails for financial-like shocks)
   294→  if (env.resourceReserves < criticalThreshold) {
   295→    const cascadeMagnitude = levyFlight(ALPHA_PRESETS.ENVIRONMENT, Math.random);
   296→
   297→    if (cascadeMagnitude > 10.0) {
   298→      // Mega-cascade (rare but devastating - supply chain collapse, hoarding)
   299→      const cascadeSize = Math.min(cascadeMagnitude / 100, 0.3); // Max 30% drop
   300→      env.resourceReserves = Math.max(0, env.resourceReserves - cascadeSize);
   301→
   302→      console.log(`\n  ⚠️ RESOURCE MEGA-CASCADE: Lévy flight triggered`);
   303→      console.log(`     Magnitude: ${cascadeMagnitude.toFixed(2)} → -${(cascadeSize * 100).toFixed(1)}% reserves`);
   304→      console.log(`     Triggered at ${(env.resourceReserves * 100).toFixed(1)}% (critical threshold)`);
   305→    }
   306→  }
   307→
   308→  // Climate cascade (positive feedbacks - methane release, ice-albedo)
   309→  if (env.climateStability < criticalThreshold) {
   310→    const cascadeMagnitude = levyFlight(ALPHA_PRESETS.ENVIRONMENT, Math.random);
   311→
   312→    if (cascadeMagnitude > 10.0) {
   313→      // Mega-cascade (tipping point triggers positive feedbacks)
   314→      const cascadeSize = Math.min(cascadeMagnitude / 150, 0.25); // Max 25% drop
   315→      env.climateStability = Math.max(0, env.climateStability - cascadeSize);
   316→
   317→      console.log(`\n  ⚠️ CLIMATE MEGA-CASCADE: Tipping point cascade`);
   318→      console.log(`     Magnitude: ${cascadeMagnitude.toFixed(2)} → -${(cascadeSize * 100).toFixed(1)}% stability`);
   319→      console.log(`     Feedback loop: permafrost methane / ice-albedo effect activated`);
   320→    }
   321→  }
   322→
   323→  // Biodiversity cascade (ecosystem collapse cascades)
   324→  if (env.biodiversityIndex < criticalThreshold) {
   325→    const cascadeMagnitude = levyFlight(ALPHA_PRESETS.ENVIRONMENT, Math.random);
   326→
   327→    if (cascadeMagnitude > 10.0) {
   328→      // Mega-cascade (keystone species loss triggers avalanche)
   329→      const cascadeSize = Math.min(cascadeMagnitude / 100, 0.35); // Max 35% drop
   330→      env.biodiversityIndex = Math.max(0, env.biodiversityIndex - cascadeSize);
   331→
   332→      console.log(`\n  ⚠️ BIODIVERSITY MEGA-CASCADE: Keystone species collapse`);
   333→      console.log(`     Magnitude: ${cascadeMagnitude.toFixed(2)} → -${(cascadeSize * 100).toFixed(1)}% biodiversity`);
   334→      console.log(`     Trophic cascade: keystone predator/pollinator loss → ecosystem avalanche`);
   335→    }
   336→  }
   337→
   338→  // === CRISIS TRIGGERS ===
   339→  checkEnvironmentalCrises(state);
   340→}
   341→
   342→/**
   343→ * Check if environmental accumulation has crossed crisis thresholds
   344→ * 
   345→ * Crises trigger QoL impacts and potentially extinction scenarios.
   346→ */
   347→function checkEnvironmentalCrises(state: GameState): void {
   348→  const env = state.environmentalAccumulation;
   349→  const qol = state.qualityOfLifeSystems;
   350→  
   351→  // RESOURCE CRISIS: Reserves depleted below 30%
   352→  if (env.resourceReserves < 0.3 && !env.resourceCrisisActive) {
   353→    env.resourceCrisisActive = true;
   354→    updateCatastropheTracking(state, 'resource_crisis', 1.0 - env.resourceReserves);
   355→    try {
   356→      console.log(`\n⚠️  RESOURCE CRISIS TRIGGERED (Month ${state.currentMonth})`);
   357→      console.log(`   Resource Reserves: ${(env.resourceReserves * 100).toFixed(1)}%`);
   358→      console.log(`   Impact: Manufacturing disrupted, QoL declining\n`);
   359→    } catch (e) { /* Ignore EPIPE */ }
   360→
   361→    // Log event
   362→    state.eventLog.push({
   363→      id: `resource-crisis-${state.currentMonth}`,
   364→      type: 'crisis',
   365→      title: 'Resource Crisis',
   366→      timestamp: state.currentMonth,
   367→      severity: 'critical',
   368→      agent: 'environmental',
   369→      description: `Resource Crisis: Reserves depleted to ${(env.resourceReserves * 100).toFixed(1)}%`,
   370→      effects: {
   371→        materialAbundance: -0.3,
   372→        energyAvailability: -0.2,
   373→        socialStability: -0.3
   374→      }
   375→    });
   376→
   377→    // Immediate QoL impacts
   378→    qol.materialAbundance *= 0.7; // 30% drop in material goods
   379→    qol.energyAvailability *= 0.8; // 20% drop in energy
   380→    state.globalMetrics.socialStability = Math.max(0, state.globalMetrics.socialStability - 0.3);
   381→
   382→    // Population impact: Initial famine/scarcity deaths (0.5-1% casualties)
   383→    // SEMI-GLOBAL: Affects food/water insecure regions (~25% of world)
   384→    // 0.8% mortality rate in exposed regions
   385→    const { addAcuteCrisisDeaths } = require('./populationDynamics');
   386→    addAcuteCrisisDeaths(
   387→      state,
   388→      0.008,
   389→      'Resource crisis - famine/scarcity (vulnerable regions)',
   390→      0.25,
   391→      'famine',
   392→      {
   393→        causes: [
   394→          { cause: RootCause.resource, weight: 0.50, confidence: 'MEDIUM' },
   395→          { cause: RootCause.inequality, weight: 0.35, confidence: 'MEDIUM' },
   396→          { cause: RootCause.demographic, weight: 0.15, confidence: 'MEDIUM' }
   397→        ],
   398→        evidence: 'Steffen et al. planetary boundaries + Burke poverty vulnerability',
   399→        mechanism: 'Resource depletion (phosphorus, water) × poverty × population pressure → famine'
   400→      },
   401→      'MEDIUM'
   402→    );
   403→  }
   404→  
   405→  // POLLUTION CRISIS: Pollution exceeds 70%
   406→  if (env.pollutionLevel > 0.7 && !env.pollutionCrisisActive) {
   407→    env.pollutionCrisisActive = true;
   408→    updateCatastropheTracking(state, 'pollution_crisis', env.pollutionLevel);
   409→    try {
   410→      console.log(`\n⚠️  POLLUTION CRISIS TRIGGERED (Month ${state.currentMonth})`);
   411→      console.log(`   Pollution Level: ${(env.pollutionLevel * 100).toFixed(1)}%`);
   412→      console.log(`   Impact: Health crisis, ecosystem contamination\n`);
   413→    } catch (e) { /* Ignore EPIPE */ }
   414→
   415→    state.eventLog.push({
   416→      id: `pollution-crisis-${state.currentMonth}`,
   417→      type: 'crisis',
   418→      title: 'Pollution Crisis',
   419→      timestamp: state.currentMonth,
   420→      severity: 'critical',
   421→      agent: 'environmental',
   422→      description: `Pollution Crisis: Pollution level ${(env.pollutionLevel * 100).toFixed(1)}%`,
   423→      effects: {
   424→        healthcareQuality: -0.25,
   425→        diseasesBurden: 0.3,
   426→        ecosystemHealth: -0.4,
   427→        qualityOfLife: -0.25
   428→      }
   429→    });
   430→
   431→    // Immediate QoL impacts
   432→    qol.healthcareQuality *= 0.75; // 25% drop (pollution-related diseases)
   433→    qol.diseasesBurden = Math.min(1, qol.diseasesBurden + 0.3); // Disease burden increases
   434→    qol.ecosystemHealth *= 0.6; // 40% drop in ecosystem health
   435→    state.globalMetrics.qualityOfLife = Math.max(0, state.globalMetrics.qualityOfLife - 0.25);
   436→
   437→    // Population impact: Pollution-related disease deaths (0.3-0.5% casualties)
