   579→ *
   580→ * Trust Components (Research-Backed):
   581→ * 1. Alignment Perception (25%) - Observable AI behavior (not true alignment - unobservable)
   582→ * 2. Performance (35%) - How well AI works in practice (MOST IMPORTANT)
   583→ * 3. Demonstrated Benefits (25%) - Has AI improved quality of life tangibly?
   584→ * 4. Safety Record (15%) - Track record of no major incidents
   585→ * 5. Capability Fear (penalty) - Only rapid changes cause fear, not absolute levels
   586→ */
   587→export function calculateComprehensiveTrustInAI(state: GameState): number {
   588→  // 1. ALIGNMENT PERCEPTION (25% weight)
   589→  // Observable behavior, NOT true alignment (which is unobservable)
   590→  const alignmentPerception = calculateAlignmentPerception(state);
   591→
   592→  // 2. PERFORMANCE (35% weight) - MOST IMPORTANT
   593→  // How well AI actually works in practice
   594→  const performance = calculateAIPerformance(state);
   595→
   596→  // 3. DEMONSTRATED BENEFITS (25% weight)
   597→  const qol = state.globalMetrics.qualityOfLife;
   598→  const demonstratedBenefits = qol > 0.5 ? 0.25 : qol * 0.5; // Scales with QoL
   599→
   600→  // 4. SAFETY RECORD (15% weight)
   601→  const safetyRecord = calculateSafetyRecord(state);
   602→
   603→  // Base trust from positive factors
   604→  const baseTrust = alignmentPerception + performance + demonstratedBenefits + safetyRecord;
   605→
   606→  // 5. CAPABILITY FEAR (penalty only on rapid changes)
   607→  const capabilityFear = calculateCapabilityFear(state);
   608→
   609→  // Final trust with bounds
   610→  const finalTrust = Math.max(0, Math.min(1, baseTrust - capabilityFear));
   611→
   612→  return finalTrust;
   613→}
