   615→/**
   616→ * Calculate alignment perception component of trust (0-0.25 scale)
   617→ * FIX #2A (Oct 19, 2025): Renamed from "alignment quality"
   618→ * People observe BEHAVIOR, not true alignment (which is internal and often hidden)
   619→ * Research: McKinsey (2024) - trust based on observed outcomes, not internal states
   620→ */
   621→function calculateAlignmentPerception(state: GameState): number {
   622→  const totalAIs = state.aiAgents.length;
   623→  if (totalAIs === 0) return 0.2; // Moderate default
   624→
   625→  // Public perception based on detected issues
   626→  // Only count detected misalignments (revealedCapability significantly differs) - people can't see hidden issues
   627→  const { calculateTotalCapabilityFromProfile } = require('./capabilities');
   628→  const detectedMisalignments = state.aiAgents.filter(ai => {
   629→    const trueCap = calculateTotalCapabilityFromProfile(ai.trueCapability);
   630→    const revealedCap = calculateTotalCapabilityFromProfile(ai.revealedCapability);
   631→    return ai.alignment < 0.5 && Math.abs(trueCap - revealedCap) < 0.1; // Detected if no hiding
   632→  }).length;
   633→
   634→  const perceptionRate = 1 - (detectedMisalignments / totalAIs);
   635→
   636→  // Scale to 0-0.25 (25% of total trust)
   637→  return perceptionRate * 0.25;
   638→}
