   640→/**
   641→ * Calculate AI performance component of trust (0-0.35 scale)
   642→ * FIX #2A (Oct 19, 2025): NEW FUNCTION - most important trust driver per research
   643→ *
   644→ * Research:
   645→ * - DORA (2024): Performance = task completion * reliability
   646→ * - McKinsey (2024): Performance matters more than explanations
   647→ * - Edelman (2024): Consistency and demonstrated value drive trust
   648→ *
   649→ * Performance = how well AI works (results) + how reliably (no failures)
   650→ */
   651→function calculateAIPerformance(state: GameState): number {
   652→  const qol = state.globalMetrics.qualityOfLife;
   653→  const previousQoL = assertStateProperty(
   654→    state.globalMetrics,
   655→    'previousQoL',
   656→    { location: 'calculateAIPerformance', month: state.currentMonth }
   657→  );
   658→  const qolTrend = qol - previousQoL;
   659→
   660→  // Performance baseline from QoL (is AI making life better?)
   661→  // If QoL > 0.5, AI is working well
   662→  const performanceFromResults = Math.min(0.20, qol * 0.3);
   663→
   664→  // Positive trend bonus (AI improving over time)
   665→  const trendBonus = qolTrend > 0 ? Math.min(0.05, qolTrend * 0.5) : 0;
   666→
   667→  // Reliability: no major failures in last 12 months
   668→  const recentFailures = state.eventLog.filter(
   669→    event => event.type === 'crisis' &&
   670→             event.agent?.startsWith('ai-') && // AI-caused crisis (optional chaining for safety)
   671→             state.currentMonth - event.timestamp < 12
   672→  ).length;
   673→
   674→  const reliabilityBonus = Math.max(0, 0.10 - (recentFailures * 0.02));
   675→
   676→  // Performance = results + trend + reliability, capped at 35%
   677→  return Math.min(0.35, performanceFromResults + trendBonus + reliabilityBonus);
   678→}
