   688→    event => event.type === 'crisis' &&
   689→             event.agent?.startsWith('ai-') && // AI-caused incident (optional chaining for safety)
   690→             state.currentMonth - event.timestamp < 12
   691→  ).length;
   692→
   693→  // No incidents in last 12 months = full trust (0.15)
   694→  // Each incident reduces trust
   695→  const safetyScore = Math.max(0, 0.15 - (recentIncidents * 0.05));
   696→
   697→  return safetyScore;
