   704→function calculateCapabilityFear(state: GameState): number {
   705→  // Track capability change rate (requires state to store previous capability)
   706→  const currentCapability = state.aiAgents.length > 0
   707→    ? state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0) / state.aiAgents.length
   708→    : 0;
