   719→  // Store for next iteration
   720→  (state as any).previousAICapability = currentCapability;
   721→
   722→  // Fear only triggers on rapid changes (>0.5/month)
   723→  if (capabilityChange > CAPABILITY_CHANGE_FEAR_THRESHOLD) {
