   861→  // Proxy: Low QoL despite high AI capability suggests mistakes
   862→  const avgCapability = state.aiAgents.length > 0
   863→    ? state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0) / state.aiAgents.length
   864→    : 0;
   865→  const qol = state.globalMetrics.qualityOfLife;
   866→  const errorRate = avgCapability > 2.0 && qol < 0.5;
   867→  if (errorRate) {
