   870→
   871→  // === FIX #10A: APPLY PER-SEGMENT WITH HETEROGENEOUS MULTIPLIERS ===
   872→
   873→  if (state.society.segments && state.society.segments.length > 0) {
   874→    // Apply trust change to each segment with multipliers based on adaptability and openness
   875→    for (const seg of state.society.segments) {
