   906→    if (Math.abs(baseTrustChange) > 0.02 && state.currentMonth % 6 === 0) {
   907→      console.log(`\n🔄 TRUST DYNAMICS (Month ${state.currentMonth}) - HETEROGENEOUS`);
   908→      console.log(`   Aggregate trust: ${(state.society.trustInAI * 100).toFixed(1)}%`);
   909→      console.log(`   Base change: ${baseTrustChange > 0 ? '+' : ''}${(baseTrustChange * 100).toFixed(2)}%`);
   910→
