   912→      const sortedSegs = [...state.society.segments].sort((a, b) => b.trustInAI - a.trustInAI);
   913→      console.log(`   Highest trust: ${sortedSegs[0].name} (${(sortedSegs[0].trustInAI * 100).toFixed(1)}%)`);
   914→      console.log(`   Lowest trust: ${sortedSegs[sortedSegs.length - 1].name} (${(sortedSegs[sortedSegs.length - 1].trustInAI * 100).toFixed(1)}%)`);
   915→      console.log(`   Elite-mass gap: ${((state.society.eliteMassGap || 0) * 100).toFixed(1)}%`);
   916→      console.log(`   Polarization: ${((state.society.polarizationIndex || 0) * 100).toFixed(1)}%`);
   917→
   918→      if (baseTrustChange > 0) {
   919→        console.log(`   Recovery factors: Education=${state.policies?.aiEducationCampaigns?.active ? 'YES' : 'NO'}, Benefits=${qolTrend > 0 ? 'YES' : 'NO'}, Safety=${recentIncidents === 0 ? 'YES' : 'NO'}, Performance=${performanceImproving ? 'YES' : 'NO'}`);
   920→      } else {
   921→        console.log(`   Decay factors: Incidents=${currentMonthIncidents}, New misalignments=${newMisalignments}, Errors=${errorRate ? 'YES' : 'NO'}`);
   922→      }
   923→    }
   924→  } else {
   925→    // === FALLBACK: GLOBAL TRUST (no segments) ===
   926→    // Cap change
   927→    baseTrustChange = Math.max(-0.1, Math.min(TRUST_RECOVERY_CAP, baseTrustChange));
   928→
   929→    // Update society trust (stored separately for recovery mechanics)
   930→    if (!state.society.trustInAI) {
   931→      // Initialize if not present
   932→      state.society.trustInAI = calculateComprehensiveTrustInAI(state);
   933→    }
   934→    state.society.trustInAI = Math.max(0, Math.min(1, state.society.trustInAI + baseTrustChange));
   935→
