   937→    if (Math.abs(baseTrustChange) > 0.02 && state.currentMonth % 6 === 0) {
   938→      console.log(`\n🔄 TRUST DYNAMICS (Month ${state.currentMonth}) - GLOBAL`);
   939→      console.log(`   Trust level: ${(state.society.trustInAI * 100).toFixed(1)}%`);
   940→      console.log(`   Monthly change: ${baseTrustChange > 0 ? '+' : ''}${(baseTrustChange * 100).toFixed(2)}%`);
   941→      if (baseTrustChange > 0) {
