   953→function calculateCascadingFailureMultiplier(state: GameState): number {
   954→  const activeCrises = [
   955→    // Environmental (4 possible)
   956→    state.environmentalAccumulation.resourceCrisisActive,
   957→    state.environmentalAccumulation.pollutionCrisisActive,
   958→    state.environmentalAccumulation.climateCrisisActive,
